  /* Rotating headline word (3D flip) */
  const words = $$('.rot__w'); let wi = 0;
  if (!reduce) setInterval(() => {
    const cur = words[wi]; wi = (wi + 1) % words.length; const nxt = words[wi];
    cur.classList.remove('is-on'); cur.classList.add('is-out');
    nxt.classList.remove('is-out'); nxt.classList.add('is-on');
    setTimeout(() => cur.classList.remove('is-out'), 700);
  }, 2600);

  /* ECG heartbeat — a pulse travels across the hero */
  (function ecg() {
    const c = $('#ecg'); if (!c) return;
    const ctx = c.getContext('2d'); const dpr = Math.min(devicePixelRatio || 1, 2);
    let W, H, x = 0, speed = 3.2, boost = 0, visible = true;
    const pts = [];
    const size = () => { W = c.clientWidth; H = c.clientHeight; c.width = W * dpr; c.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0); };
    new ResizeObserver(size).observe(c); size();
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; }).observe(c);
    $('#hero').addEventListener('pointermove', () => { boost = 4; }, { passive: true });
    // QRS complex shape, repeated every 260px
    const shape = (u) => {
      const p = u % 260;
      if (p < 40) return 0; if (p < 55) return -8 * Math.sin((p - 40) / 15 * Math.PI);
      if (p < 70) return 0; if (p < 76) return 10; if (p < 84) return -58; if (p < 92) return 26;
      if (p < 98) return 0; if (p < 130) return -14 * Math.sin((p - 98) / 32 * Math.PI); return 0;
    };
    function frame() {
      requestAnimationFrame(frame);
      if (!visible) return;
      const step = speed + boost; boost *= .94;
      for (let s = 0; s < step; s += 1) { x += 1; pts.push([x, shape(x)]); }
      while (pts.length && pts[0][0] < x - W) pts.shift();
      ctx.clearRect(0, 0, W, H);
      const off = x - W, mid = H / 2;
      const grad = ctx.createLinearGradient(0, 0, W, 0);
      grad.addColorStop(0, 'rgba(210,74,132,0)'); grad.addColorStop(.7, 'rgba(210,74,132,.55)'); grad.addColorStop(1, 'rgba(255,147,211,1)');
      ctx.lineJoin = 'round';
      const path = new Path2D();
      for (let i = 0; i < pts.length; i += 2) { const X = pts[i][0] - off, Y = mid + pts[i][1]; i ? path.lineTo(X, Y) : path.moveTo(X, Y); }
      ctx.strokeStyle = grad; ctx.globalAlpha = .25; ctx.lineWidth = 9; ctx.stroke(path);   // soft glow pass
      ctx.globalAlpha = 1; ctx.lineWidth = 2.2; ctx.stroke(path);
      const last = pts[pts.length - 1];
      if (last) { ctx.fillStyle = 'rgba(255,147,211,.35)'; ctx.beginPath(); ctx.arc(W, mid + last[1], 9, 0, 7); ctx.fill(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(W, mid + last[1], 3.5, 0, 7); ctx.fill(); }
    }
    for (let i = 0; i < Math.max(W, 1600); i++) { x += 1; pts.push([x, shape(x)]); }
    frame();
  })();

  /* Crest fills with gold in a loop (fill 45% · hold · drain), year follows the level.
     Runs only while the crest is on screen and the tab is visible. */
  (function crestFill() {
    const cf = $('#cf'), yr = $('#cfyear'); if (!cf) return;
    if (reduce) { yr.textContent = '2026'; return; }
    const LOOP = 9000, ease = (p) => p < .5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
    let t0 = 0, pausedAt = 0, running = false, onScreen = true;
    const level = (p) => p < .45 ? ease(p / .45) : p < .85 ? 1 : 1 - ease((p - .85) / .15);
    const tick = () => { if (!running) return; const p = ((Date.now() - t0) % LOOP) / LOOP; yr.textContent = String(Math.round(1936 + 90 * Math.min(1, level(p)))); };
    const play = () => {
      if (running || !onScreen || document.hidden) return;
      running = true;
      if (!cf.classList.contains('is-on')) { t0 = Date.now(); cf.classList.add('is-on'); }
      else t0 += Date.now() - pausedAt;
      cf.classList.remove('is-paused');
    };
    const pause = () => { if (!running) return; running = false; pausedAt = Date.now(); cf.classList.add('is-paused'); };
    setInterval(tick, 40);
    new IntersectionObserver(([e]) => { onScreen = e.isIntersecting; onScreen ? play() : pause(); }, { threshold: .3 }).observe(cf);
    document.addEventListener('visibilitychange', () => (document.hidden ? pause() : play()));
    setTimeout(play, 700);
  })();

  /* Symptom routing (no diagnosis, red flags → 112) */
  if ($('#ask')) $('#ask').addEventListener('submit', (e) => {
    e.preventDefault();
    const q = norm($('#ask-q').value), out = $('#ask-out');
    if (!q) { out.innerHTML = ''; return; }
    if (RED_FLAGS.some((f) => q.includes(f))) { out.innerHTML = `<div class="warn"><b>Може да е спешно. Обадете се на 112.</b><br>Спешно отделение на ИСУЛ: 02 9432 637</div>`; return; }
    const m = SYMPTOMS.find((s) => s.k.some((k) => q.includes(k)));
    if (!m) { out.innerHTML = `<div class="warn" style="background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.18);color:#fff">Не открихме насочване. Обадете се на 02 9432 207 за информация.</div>`; return; }
    const sp = SPECIALTIES.find((s) => s.id === m.spec), cl = CLINICS.filter((c) => c.spec === m.spec);
    out.innerHTML = `<a href="index.html#/specialties/${sp.id}"><span><small>Специалност</small><br><b>${sp.name}</b></span><span>→</span></a>`
      + cl.map((c, i) => `<a href="index.html#/clinics/${c.id}" style="animation-delay:${(i + 1) * 80}ms"><span><small>Клиника</small><br><b>${c.short || c.name}</b></span><span>→</span></a>`).join('')
      + `<a href="index.html#/book?spec=${sp.id}" style="animation-delay:${(cl.length + 1) * 80}ms;background:rgba(210,74,132,.25);border-color:rgba(210,74,132,.6)"><b>Запази час</b><span>→</span></a><p class="ask__note">Насочването е ориентировъчно и не е диагноза.</p>`;
  });

  /* 3D clinic ring */
  (function ring() {
    const ul = $('#ring'); if (!ul) return;
    const groups = CLINIC_GROUPS.map((g) => ({ g, items: CLINICS.filter((c) => c.group === g) }));
    const n = groups.length, step = 360 / n, w = ul.offsetWidth || 300, R = Math.round((w / 2) / Math.tan(Math.PI / n)) + 24;
    ul.innerHTML = groups.map(({ g, items }, i) => `<li style="transform:rotateY(${i * step}deg) translateZ(${R}px)"><a href="index.html#/clinics"><span class="n">${String(items.length).padStart(2, '0')}</span><b>${g}</b><ul>${items.slice(0, 4).map((c) => `<li>${(c.short || c.name).replace('Клиника по ', '')}</li>`).join('')}${items.length > 4 ? `<li>и още ${items.length - 4}</li>` : ''}</ul></a></li>`).join('');
    let a = 0, drag = false, lx = 0, auto = !reduce;
    const set = () => { ul.style.transform = `translateZ(${-R}px) rotateY(${a}deg)`; };
    $('#cprev').addEventListener('click', () => { auto = false; a += step; set(); });
    $('#cnext').addEventListener('click', () => { auto = false; a -= step; set(); });
    const stage = $('#ring3d');
    stage.addEventListener('pointerdown', (e) => { if (e.target.closest('a')) return; drag = true; auto = false; lx = e.clientX; ul.style.transition = 'none'; });
    addEventListener('pointermove', (e) => { if (!drag) return; a += (e.clientX - lx) * .25; lx = e.clientX; set(); });
    addEventListener('pointerup', () => { if (!drag) return; drag = false; ul.style.transition = ''; a = Math.round(a / step) * step; set(); });
    stage.addEventListener('pointerenter', () => { auto = false; });
    setInterval(() => { if (auto && innerWidth > 760) { a -= step; set(); } }, 3200);
    set();
  })();

  /* ---------- Information part ---------- */
  const fmt = (iso) => iso.split('-').reverse().join('.');
  const catOf = (n) => (n.cat === 'Болницата' ? 'Новини' : n.cat);

  /* News column: one featured + list */
  (function news() {
    const box = $('#newsx'); if (!box) return;
    const [f, ...rest] = NEWS;
    box.innerHTML = `<a class="nfeat" href="index.html#/news"><img src="${f.img}" alt="" loading="lazy"><div><p class="nmeta"><b>${catOf(f)}</b><time datetime="${f.date}">${fmt(f.date)}</time></p><h3>${f.title}</h3><p>${f.ex}</p></div></a>`
      + `<ul class="nlist">${rest.slice(0, 4).map((n) => `<li><a class="nrow" href="index.html#/news"><img src="${n.img}" alt="" loading="lazy"><div><p class="nmeta"><b>${catOf(n)}</b><time datetime="${n.date}">${fmt(n.date)}</time></p><h3>${n.title}</h3></div></a></li>`).join('')}</ul>`;
  })();

