      { n: 'д-р Наталия Боцевска', t: 'Интервю: първите симптоми на макулната дегенерация', img: 'assets/photos/1791544362.jpg', pos: '50% 20%' },
      { n: 'д-р Вера Мегданова, дм', t: 'Номинация за принос към българската онкология', img: 'assets/photos/1790944963.jpg', pos: '100% 25%', zoom: 1.6, origin: '76% 30%' }
