      <span class="jb2__t"><span class="jb2__meta"><em>${j.type}</em><time>${j.date}</time></span><b>${j.title}</b><small>${(C[j.clinic] || {}).name || ''}</small><span class="jb2__lead">${j.lead}</span></span>
